package android.graphics; import java.util.*; public class Path {public enum Direction{CW}public final List<float[]> points=new ArrayList<>();public void moveTo(float x,float y){points.add(new float[]{x,y});}public void lineTo(float x,float y){points.add(new float[]{x,y});}public void cubicTo(float a,float b,float c,float d,float e,float f){points.add(new float[]{e,f});}public void addRect(float l,float t,float r,float b,Direction d){moveTo(l,t);lineTo(r,t);lineTo(r,b);lineTo(l,b);close();}public void close(){}public void addCircle(float x,float y,float r,Direction d){points.add(new float[]{x,y});}}
